%[text] # Import data from spreadsheet
%[text] Script for importing data from the following spreadsheet:
%[text] ```
%[text]   Workbook: pd_tbl_pubchem.xlsx
%[text]   Worksheet: pd_tbl_pubchem
%[text] ```
%[text] Auto-generated by MATLAB on 06-Dec-2025 08:33:17
%[text] ## Set up the Import Options and import the data
opts = spreadsheetImportOptions("NumVariables", 18);

% Specify sheet and range
opts.Sheet = "pd_tbl_pubchem";
opts.DataRange = "A2:R119";

% Specify column names and types
opts.VariableNames = ["AtomicNumber", "Symbol", "Name", "AtomicMass", "CPKHexColor", "ElectronConfiguration", "Electronegativity", "AtomicRadius", "IonizationEnergy", "ElectronAffinity", "OxidationStates", "StandardState", "MeltingPoint", "BoilingPoint", "Density", "GroupBlock", "YearDiscovered", "PropertiesPredicted"];
opts.VariableTypes = ["double", "string", "string", "double", "string", "string", "double", "double", "double", "double", "string", "string", "double", "double", "double", "string", "double", "double"];

% Specify variable properties
opts = setvaropts(opts, ["Symbol", "Name", "CPKHexColor", "ElectronConfiguration"], "WhitespaceRule", "preserve");
opts = setvaropts(opts, ["Symbol", "Name", "CPKHexColor", "ElectronConfiguration", "OxidationStates", "StandardState", "GroupBlock"], "EmptyFieldRule", "auto");
opts = setvaropts(opts, ["AtomicNumber", "AtomicMass", "Electronegativity", "AtomicRadius", "IonizationEnergy", "ElectronAffinity", "MeltingPoint", "BoilingPoint", "Density", "YearDiscovered", "PropertiesPredicted"], "FillValue", -1);

% Import the data
pd_tbl_pubchem = readtable("pd_tbl_pubchem.xlsx", opts, "UseExcel", false);
%%
%[text] ## Compute Electron Shells
%[text] Convert electron configuration into respective electron shells of elements.
number = size(pd_tbl_pubchem, 1);

shell_cnts = string(number);
num_shells_all = zeros(1, number);

for i = 1:number
    shell_cnt = config_to_shell_counts(pd_tbl_pubchem.ElectronConfiguration(i), pd_tbl_pubchem);
    num_shells = size(shell_cnt, 2);

    shell_cnt = arrayfun(@num2str, shell_cnt, "UniformOutput", false);
    shell_cnt = join(shell_cnt, ",");
    shell_cnt = string(shell_cnt);

    shell_cnts(i) = shell_cnt;
    num_shells_all(i) = num_shells;
end

pd_tbl_pubchem.ElectronShells = shell_cnts';
pd_tbl_pubchem.NumShells = num_shells_all';
pd_tbl_pubchem %[output:24555c83]
