function [counts, countsStr] = config_to_shell_counts(cfgStr, pd_tbl_pubchem)
%CONFIG_TO_SHELL_COUNTS Convert an electron-configuration string into per-shell counts.
%   [COUNTS, COUNTSTR] = CONFIG_TO_SHELL_COUNTS(CFGSTR, PD_TBL_PUBCHEM)
%   - CFGSTR is a string like "[Xe]6s2 4f14 5d10 6p5".
%   - PD_TBL_PUBCHEM is a table with a column "Symbol" and a column
%     "ElectronConfiguration" (cellstr or string), used to expand noble-gas
%     bracket cores (e.g. [Xe]).
%
%   COUNTS is a numeric row vector where COUNTS(n) is the total number of
%   electrons in principal shell n. COUNTSTR is a comma-separated string
%   representation (e.g. "2,8,18,32,18,7").
%
%   The function:
%     - replaces bracketed cores like [Xe] by looking up Xe in the table
%       and substituting its ElectronConfiguration (recursive expansion
%       if the core itself uses brackets),
%     - parses tokens like "6s2", "4f14", "5d10" and sums electrons by the
%       principal quantum number (the leading digit).
%
%   Example:
%     pd = table({'Xe'},{'[Kr]4d10 5s2 5p6'},'VariableNames',{'Symbol','ElectronConfiguration'});
%     [c,s] = config_to_shell_counts('[Xe]6s2 4f14 5d10 6p5', pd);
%     % c -> [2 8 18 32 18 7], s -> "2,8,18,32,18,7"
%
%   Notes:
%   - This is a simple text-based parser that assumes standard notation
%     like "ns#", "nd#", "np#", "nf#", etc. It ignores orbital ordering
%     subtleties and directly uses the numeric principal quantum number
%     given in the string.
%   - Make sure pd_tbl_pubchem.Symbol contains standard element symbols
%     (e.g. 'Xe') and ElectronConfiguration entries are strings like
%     "[Kr]4d10 5s2 5p6" (no nested metadata).

    if nargin < 2
        error('Provide cfgStr and pd_tbl_pubchem table.');
    end

    % Normalize inputs to char
    if isstring(cfgStr)
        cfgStr = char(cfgStr);
    end

    % Copy working string
    working = strtrim(cfgStr);

    % Expand any bracketed cores like [Xe] by looking up the symbol in the table.
    % Repeat until no brackets remain or we cannot expand further.
    maxIter = 10; % safety to avoid infinite loops
    iter = 0;
    while ~isempty(regexp(working, '\[[^\]]+\]', 'once')) && iter < maxIter
        iter = iter + 1;
        % find all bracket tokens
        tokens = regexp(working, '\[([^\]]+)\]', 'tokens');
        if isempty(tokens)
            break;
        end
        replaced = false;
        for k = 1:numel(tokens)
            sym = strtrim(tokens{k}{1}); % e.g. 'Xe'
            % find in table (case-sensitive match for chemical symbol)
            idx = find(strcmp(pd_tbl_pubchem.Symbol, sym), 1);
            if isempty(idx)
                % try case-insensitive fallback
                idx = find(strcmpi(pd_tbl_pubchem.Symbol, sym), 1);
            end
            if isempty(idx)
                % If not found, remove the bracket (assume core unknown) to avoid infinite loop
                % Alternatively, you could error out here.
                warning('Core symbol [%s] not found in pd_tbl_pubchem; removing bracket.', sym);
                working = regexprep(working, ['\[' regexpescape(sym) '\]'], '');
            else
                coreCfg = pd_tbl_pubchem.ElectronConfiguration{idx};
                if isstring(coreCfg)
                    coreCfg = char(coreCfg);
                end
                if isempty(coreCfg)
                    warning('Empty ElectronConfiguration for symbol %s; removing bracket.', sym);
                    working = regexprep(working, ['\[' regexpescape(sym) '\]'], '');
                else
                    % replace the first occurrence of [sym] with the core's configuration
                    % ensure spacing so tokens stay separate
                    coreCfg = strtrim(coreCfg);
                    working = regexprep(working, ['\[' regexpescape(sym) '\]'], [' ' coreCfg ' '], 'once');
                    replaced = true;
                end
            end
        end
        % normalize whitespace
        working = strtrim(regexprep(working, '\s+', ' '));
        if ~replaced
            break;
        end
    end

    % Now parse orbital tokens of the form "<n><subshell><count>", e.g. "6s2" or "4f14".
    % Allow optional whitespace between parts although typical strings have none.
    % Token regex: (\d+)\s*([spdfg])\s*(\d+)
    tok = regexp(working, '(\d+)\s*([spdfg])\s*(\d+)', 'tokens');

    if isempty(tok)
        % If nothing matched, return empty
        counts = [];
        countsStr = '';
        return;
    end

    % Determine max principal quantum number present
    ns = cellfun(@(t) str2double(t{1}), tok);
    maxN = max(ns);

    counts = zeros(1, maxN);

    for i = 1:numel(tok)
        t = tok{i};
        n = str2double(t{1});
        % subshell = t{2}; % not used except for debugging
        c = str2double(t{3});
        if isnan(n) || isnan(c)
            continue;
        end
        counts(n) = counts(n) + c;
    end

    % Trim trailing zeros (optional) but keep from shell 1 up to max nonzero shell
    lastNZ = find(counts ~= 0, 1, 'last');
    if isempty(lastNZ)
        counts = [];
    else
        counts = counts(1:lastNZ);
    end

    % Create comma-separated string
    countsStr = sprintf('%d,', counts);
    if ~isempty(countsStr)
        countsStr(end) = []; % remove trailing comma
    end
end

% Helper to escape regex meta-characters for a literal token
function s = regexpescape(t)
    % minimal escaping for characters that may appear in symbol
    s = regexprep(t, '([\\\^\$\.\|\?\*\+\(\)\[\]\{\}])', '\\$1');
end
